    let ext = '.ogg';
    if (mime.includes('mp4') || mime.includes('m4a')) ext = '.m4a';
    else if (mime.includes('mpeg') || mime.includes('mp3')) ext = '.mp3';
    else if (mime.includes('wav')) ext = '.wav';

    const uploadDir = path.join(projectDir, '.whatsapp-uploads');
