        const res = await api?.requestPairingCode(phone);
        if (res?.success && res?.code) {
          const rawCode = String(res.code).replace(/[^a-zA-Z0-9]/g, '');
          const formatted = rawCode.length === 8 ? `${rawCode.slice(0, 4)}-${rawCode.slice(4)}` : res.code;
