  // Google Login Click (Gated behind Step 1)
  btnGoogleLogin.addEventListener('click', async () => {
    if (!isConnected) {
      appendLog('warn', '⚠️ Complete Step 1 (Link WhatsApp) first before connecting your Google Account.');
